'use strict';

function requireString(value) {
  if (typeof value !== 'string') throw new TypeError('value must be a string');
  return value;
}

const transformers = Object.freeze({
  plain(value) {
    return requireString(value);
  },
  upper(value) {
    return requireString(value).toUpperCase();
  },
  snake(value) {
    return requireString(value).trim().replace(/\s+/gu, '_').toLowerCase();
  },
  reverse(value) {
    return Array.from(requireString(value)).reverse().join('');
  }
});

function getTextTransformer(name) {
  if (typeof name !== 'string') return transformers.plain;
  const key = name.toLowerCase();
  return transformers[key] || transformers.plain;
}

module.exports = { getTextTransformer };

