'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['getTextTransformer']);
assert.strictEqual(typeof api.getTextTransformer, 'function');
const { getTextTransformer } = api;

const plain = getTextTransformer('plain');
const upper = getTextTransformer('upper');
const snake = getTextTransformer('snake');
const reverse = getTextTransformer('reverse');

assert.strictEqual(getTextTransformer(' PLAIN '), plain);
assert.strictEqual(getTextTransformer('UpPeR'), upper);
assert.strictEqual(getTextTransformer('\t SNAKE\n'), snake);
assert.strictEqual(getTextTransformer(' Reverse '), reverse);
assert.strictEqual(getTextTransformer('unknown'), plain);
assert.strictEqual(getTextTransformer('   '), plain);
assert.strictEqual(getTextTransformer(''), plain);
assert.strictEqual(getTextTransformer(null), plain);
assert.strictEqual(getTextTransformer(42), plain);

assert.strictEqual(plain(' Ab C '), ' Ab C ');
assert.strictEqual(upper('Straße'), 'STRASSE');
assert.strictEqual(snake('  One\tTWO\n three  '), 'one_two_three');
assert.strictEqual(snake('   '), '');
assert.strictEqual(snake('Already_Snake'), 'already_snake');
assert.strictEqual(reverse('A😀𝄞B'), 'B𝄞😀A');
assert.strictEqual(reverse(''), '');

for (const transformer of [plain, upper, snake, reverse]) {
  for (const invalid of [null, undefined, 1, true, {}, []]) {
    assert.throws(() => transformer(invalid), TypeError);
  }
}

const input = '  Keep Me  ';
snake(input);
assert.strictEqual(input, '  Keep Me  ');

